import React from 'react';

export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: 40, color: '#ef5350', fontFamily: 'monospace', fontSize: 13 }}>
          <div style={{ fontSize: 24, marginBottom: 16 }}>⚠️ Xato yuz berdi</div>
          <div style={{ color: '#7a99b8', marginBottom: 8 }}>{this.state.error?.message}</div>
          <button onClick={() => this.setState({ hasError: false })}
            style={{ padding: '8px 20px', background: '#ef535022', border: '1px solid #ef5350', color: '#ef5350', borderRadius: 6, cursor: 'pointer', marginTop: 16 }}>
            Qayta urinish
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}
