import React, { useState } from 'react';
import { useAuth, ROLE_CONFIG, ROLES } from '../auth/AuthContext';

export default function LoginPage() {
  const { login } = useAuth();
  const [mode, setMode] = useState('welcome'); // welcome | login | register
  const [step, setStep] = useState(1); // register: 1=info, 2=rol
  const [form, setForm] = useState({ name: '', email: '', password: '', role: '' });
  const [error, setError] = useState('');

  const generalRoles = Object.entries(ROLE_CONFIG).filter(([, v]) => v.group === 'general');
  const specialRoles = Object.entries(ROLE_CONFIG).filter(([, v]) => v.group === 'special');

  const handleLogin = (e) => {
    e.preventDefault();
    const saved = localStorage.getItem('geosat_users');
    const users = saved ? JSON.parse(saved) : [];
    const found = users.find(u => u.email === form.email && u.password === form.password);
    if (found) {
      login(found);
    } else {
      setError("Email yoki parol noto'g'ri!");
    }
  };

  const handleRegisterStep1 = (e) => {
    e.preventDefault();
    if (!form.name || !form.email || !form.password) {
      setError("Barcha maydonlarni to'ldiring!"); return;
    }
    setError('');
    setStep(2);
  };

  const handleRegister = (role) => {
    const saved = localStorage.getItem('geosat_users');
    const users = saved ? JSON.parse(saved) : [];
    if (users.find(u => u.email === form.email)) {
      setError("Bu email allaqachon ro'yxatdan o'tgan!"); setStep(1); return;
    }
    const newUser = { ...form, role, id: Date.now() };
    users.push(newUser);
    localStorage.setItem('geosat_users', JSON.stringify(users));
    login(newUser);
  };

  return (
    <div style={{
      minHeight: '100vh', background: '#080c10',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      fontFamily: 'var(--font-sans, DM Sans, sans-serif)',
      padding: 20,
    }}>
      {/* Background grid */}
      <div style={{
        position: 'fixed', inset: 0, opacity: 0.03,
        backgroundImage: 'linear-gradient(#00e676 1px, transparent 1px), linear-gradient(90deg, #00e676 1px, transparent 1px)',
        backgroundSize: '40px 40px',
        pointerEvents: 'none',
      }} />

      <div style={{ width: '100%', maxWidth: 460, position: 'relative' }}>
        {/* Logo */}
        <div style={{ textAlign: 'center', marginBottom: 32 }}>
          <div style={{ fontSize: 48, marginBottom: 8 }}>🛰️</div>
          <div style={{ fontSize: 24, fontWeight: 700, color: '#00e676', letterSpacing: 4, fontFamily: 'monospace' }}>GEOSAT UZ</div>
          <div style={{ fontSize: 12, color: '#3d5468', letterSpacing: 2, marginTop: 4 }}>SUN'IY YO'LDOSH MONITORING PLATFORMASI</div>
        </div>

        {/* Welcome screen */}
        {mode === 'welcome' && (
          <div style={{ background: '#0d1318', border: '1px solid #1e2d3d', borderRadius: 16, padding: 32 }}>
            <h2 style={{ fontSize: 18, color: '#e8f0fe', marginBottom: 8, textAlign: 'center' }}>Xush kelibsiz!</h2>
            <p style={{ fontSize: 13, color: '#7a99b8', textAlign: 'center', marginBottom: 28 }}>
              Qishloq xo'jaligi, ekologiya va yer monitoringi platformasi
            </p>
            <button onClick={() => setMode('login')} style={btnStyle('#00e676')}>
              Kirish
            </button>
            <button onClick={() => { setMode('register'); setStep(1); }} style={{ ...btnStyle('transparent'), border: '1px solid #1e2d3d', color: '#7a99b8', marginTop: 10 }}>
              Ro'yxatdan o'tish
            </button>
          </div>
        )}

        {/* Login */}
        {mode === 'login' && (
          <div style={{ background: '#0d1318', border: '1px solid #1e2d3d', borderRadius: 16, padding: 32 }}>
            <h2 style={{ fontSize: 18, color: '#e8f0fe', marginBottom: 24 }}>Kirish</h2>
            <form onSubmit={handleLogin}>
              <Input label="Email" type="email" value={form.email} onChange={v => setForm({ ...form, email: v })} />
              <Input label="Parol" type="password" value={form.password} onChange={v => setForm({ ...form, password: v })} />
              {error && <div style={{ color: '#ef5350', fontSize: 12, marginBottom: 12 }}>{error}</div>}
              <button type="submit" style={btnStyle('#00e676')}>Kirish</button>
            </form>
            <div style={{ textAlign: 'center', marginTop: 16 }}>
              <span style={{ fontSize: 12, color: '#3d5468' }}>Akkaunt yo'qmi? </span>
              <button onClick={() => { setMode('register'); setStep(1); setError(''); }} style={{ fontSize: 12, color: '#00e676', background: 'none', border: 'none', cursor: 'pointer' }}>
                Ro'yxatdan o'ting
              </button>
            </div>
          </div>
        )}

        {/* Register Step 1 */}
        {mode === 'register' && step === 1 && (
          <div style={{ background: '#0d1318', border: '1px solid #1e2d3d', borderRadius: 16, padding: 32 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
              <div style={{ width: 28, height: 28, borderRadius: '50%', background: '#00e67622', border: '1px solid #00e676', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, color: '#00e676' }}>1</div>
              <div style={{ flex: 1, height: 2, background: '#1e2d3d', borderRadius: 1 }} />
              <div style={{ width: 28, height: 28, borderRadius: '50%', background: '#1e2d3d', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, color: '#3d5468' }}>2</div>
            </div>
            <h2 style={{ fontSize: 18, color: '#e8f0fe', marginBottom: 24 }}>Ma'lumotlaringiz</h2>
            <form onSubmit={handleRegisterStep1}>
              <Input label="Ism Familiya" value={form.name} onChange={v => setForm({ ...form, name: v })} />
              <Input label="Email" type="email" value={form.email} onChange={v => setForm({ ...form, email: v })} />
              <Input label="Parol" type="password" value={form.password} onChange={v => setForm({ ...form, password: v })} />
              {error && <div style={{ color: '#ef5350', fontSize: 12, marginBottom: 12 }}>{error}</div>}
              <button type="submit" style={btnStyle('#00e676')}>Davom etish →</button>
            </form>
            <div style={{ textAlign: 'center', marginTop: 16 }}>
              <button onClick={() => { setMode('login'); setError(''); }} style={{ fontSize: 12, color: '#3d5468', background: 'none', border: 'none', cursor: 'pointer' }}>
                ← Kirish ga qaytish
              </button>
            </div>
          </div>
        )}

        {/* Register Step 2 - Rol tanlash */}
        {mode === 'register' && step === 2 && (
          <div style={{ background: '#0d1318', border: '1px solid #1e2d3d', borderRadius: 16, padding: 32 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 24 }}>
              <div style={{ width: 28, height: 28, borderRadius: '50%', background: '#00e67622', border: '1px solid #00e676', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, color: '#00e676' }}>✓</div>
              <div style={{ flex: 1, height: 2, background: '#00e676', borderRadius: 1 }} />
              <div style={{ width: 28, height: 28, borderRadius: '50%', background: '#00e67622', border: '1px solid #00e676', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, color: '#00e676' }}>2</div>
            </div>
            <h2 style={{ fontSize: 18, color: '#e8f0fe', marginBottom: 6 }}>Rolingizni tanlang</h2>
            <p style={{ fontSize: 12, color: '#7a99b8', marginBottom: 20 }}>Siz kimligingizni tanlang — interfeys shunga moslashadi</p>

            <div style={{ fontSize: 11, color: '#3d5468', letterSpacing: 1, marginBottom: 10 }}>QISHLOQ XO'JALIGI</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 16 }}>
              {generalRoles.map(([key, cfg]) => (
                <button key={key} onClick={() => handleRegister(key)} style={roleBtn(cfg.color)}>
                  <span style={{ fontSize: 22 }}>{cfg.icon}</span>
                  <span style={{ fontSize: 12, fontWeight: 600, color: '#e8f0fe' }}>{cfg.label}</span>
                  <span style={{ fontSize: 10, color: '#7a99b8', textAlign: 'center' }}>{cfg.desc}</span>
                </button>
              ))}
            </div>

            <div style={{ fontSize: 11, color: '#3d5468', letterSpacing: 1, marginBottom: 10 }}>MAXSUS ROLLAR</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
              {specialRoles.map(([key, cfg]) => (
                <button key={key} onClick={() => handleRegister(key)} style={roleBtn(cfg.color)}>
                  <span style={{ fontSize: 22 }}>{cfg.icon}</span>
                  <span style={{ fontSize: 12, fontWeight: 600, color: '#e8f0fe' }}>{cfg.label}</span>
                  <span style={{ fontSize: 10, color: '#7a99b8', textAlign: 'center' }}>{cfg.desc}</span>
                </button>
              ))}
            </div>

            <button onClick={() => setStep(1)} style={{ marginTop: 16, fontSize: 12, color: '#3d5468', background: 'none', border: 'none', cursor: 'pointer', width: '100%', textAlign: 'center' }}>
              ← Orqaga
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

function Input({ label, type = 'text', value, onChange }) {
  return (
    <div style={{ marginBottom: 14 }}>
      <label style={{ fontSize: 11, color: '#7a99b8', letterSpacing: 1, display: 'block', marginBottom: 6 }}>{label.toUpperCase()}</label>
      <input
        type={type} value={value}
        onChange={e => onChange(e.target.value)}
        style={{
          width: '100%', padding: '10px 14px', background: '#080c10',
          border: '1px solid #1e2d3d', borderRadius: 8, color: '#e8f0fe',
          fontSize: 13, outline: 'none', boxSizing: 'border-box',
        }}
        onFocus={e => e.target.style.borderColor = '#00e676'}
        onBlur={e => e.target.style.borderColor = '#1e2d3d'}
      />
    </div>
  );
}

function btnStyle(bg) {
  return {
    width: '100%', padding: '12px', borderRadius: 8, border: 'none',
    background: bg === 'transparent' ? 'transparent' : bg,
    color: bg === 'transparent' ? '#7a99b8' : '#080c10',
    fontSize: 14, fontWeight: 700, cursor: 'pointer', display: 'block',
  };
}

function roleBtn(color) {
  return {
    padding: '14px 10px', borderRadius: 10,
    border: `1px solid ${color}33`,
    background: `${color}11`,
    cursor: 'pointer', display: 'flex', flexDirection: 'column',
    alignItems: 'center', gap: 6,
    transition: 'all 0.15s',
  };
}
