import React, { useState, useRef } from 'react';
import { analyzeDisease } from '../services/gemini';

const CROPS = ["Bug'doy", "Paxta", "Makkajo'xori", "Sholi", "Pomidor", "Bodring", "Kartoshka", "Uzum", "Olma", "Boshqa"];

export default function DiseaseDetector() {
  const [image, setImage] = useState(null);
  const [imageBase64, setImageBase64] = useState('');
  const [mimeType, setMimeType] = useState('image/jpeg');
  const [cropType, setCropType] = useState("Bug'doy");
  const [result, setResult] = useState('');
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState([]);
  const fileRef = useRef();

  const handleFile = (file) => {
    if (!file) return;
    setMimeType(file.type || 'image/jpeg');
    const reader = new FileReader();
    reader.onload = (e) => {
      setImage(e.target.result);
      const base64 = e.target.result.split(',')[1];
      setImageBase64(base64);
      setResult('');
    };
    reader.readAsDataURL(file);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    handleFile(e.dataTransfer.files[0]);
  };

  const handleAnalyze = async () => {
    if (!imageBase64) return;
    setLoading(true);
    setResult('');
    try {
      const res = await analyzeDisease(imageBase64, mimeType, cropType);
      setResult(res);
      setHistory(prev => [{ image, cropType, result: res, date: new Date().toLocaleTimeString() }, ...prev.slice(0, 4)]);
    } catch (e) {
      setResult('Xato yuz berdi: ' + e.message);
    }
    setLoading(false);
  };

  return (
    <div style={{ padding: 28, flex: 1, overflowY: 'auto' }}>
      <div style={{ marginBottom: 24 }}>
        <h1 style={{ fontSize: 22, fontWeight: 700, color: '#8bc34a', marginBottom: 4 }}>🔬 AI Kasallik Aniqlash</h1>
        <p style={{ fontSize: 13, color: 'var(--text-secondary)' }}>O'simlik rasmini yuklang — Gemini AI kasallikni aniqlab, davolash choralarini tavsiya qiladi</p>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        {/* Chap — yuklash */}
        <div>
          {/* Ekin tanlash */}
          <div style={{ marginBottom: 16 }}>
            <label style={{ fontSize: 11, color: 'var(--text-muted)', letterSpacing: 1, display: 'block', marginBottom: 6 }}>EKIN TURI</label>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {CROPS.map(c => (
                <button key={c} onClick={() => setCropType(c)}
                  style={{ padding: '5px 12px', borderRadius: 20, border: `1px solid ${cropType === c ? '#8bc34a' : 'var(--border)'}`, background: cropType === c ? '#8bc34a22' : 'transparent', color: cropType === c ? '#8bc34a' : 'var(--text-secondary)', fontSize: 11, cursor: 'pointer' }}>
                  {c}
                </button>
              ))}
            </div>
          </div>

          {/* Rasm yuklash */}
          <div
            onDrop={handleDrop}
            onDragOver={e => e.preventDefault()}
            onClick={() => fileRef.current.click()}
            style={{
              border: `2px dashed ${image ? '#8bc34a' : 'var(--border)'}`,
              borderRadius: 12, padding: 20, textAlign: 'center', cursor: 'pointer',
              background: image ? '#8bc34a08' : 'var(--bg-card)', marginBottom: 16,
              minHeight: 200, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
            }}>
            <input ref={fileRef} type="file" accept="image/*" style={{ display: 'none' }}
              onChange={e => handleFile(e.target.files[0])} />
            {image ? (
              <img src={image} alt="yuklangan" style={{ maxHeight: 200, maxWidth: '100%', borderRadius: 8, objectFit: 'contain' }} />
            ) : (
              <>
                <div style={{ fontSize: 36, marginBottom: 12 }}>📸</div>
                <div style={{ fontSize: 13, color: 'var(--text-primary)', marginBottom: 4 }}>Rasm yuklash</div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>Sudrab tashlang yoki bosing</div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 4 }}>JPG, PNG, WEBP</div>
              </>
            )}
          </div>

          {image && (
            <button onClick={handleAnalyze} disabled={loading}
              style={{ width: '100%', padding: '12px', background: loading ? '#3d5468' : '#8bc34a', border: 'none', borderRadius: 8, color: '#080c10', fontSize: 14, fontWeight: 700, cursor: loading ? 'not-allowed' : 'pointer' }}>
              {loading ? '🔬 Tahlil qilinmoqda...' : '🔬 Kasallikni Aniqlash'}
            </button>
          )}

          {/* Tarix */}
          {history.length > 0 && (
            <div style={{ marginTop: 20 }}>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', letterSpacing: 1, marginBottom: 10 }}>SO'NGGI TAHLILLAR</div>
              {history.map((h, i) => (
                <div key={i} onClick={() => { setImage(h.image); setResult(h.result); setCropType(h.cropType); }}
                  style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 10px', borderRadius: 8, border: '1px solid var(--border)', marginBottom: 6, cursor: 'pointer', background: 'var(--bg-card)' }}>
                  <img src={h.image} alt="" style={{ width: 36, height: 36, borderRadius: 4, objectFit: 'cover' }} />
                  <div>
                    <div style={{ fontSize: 12, color: 'var(--text-primary)' }}>{h.cropType}</div>
                    <div style={{ fontSize: 10, color: 'var(--text-muted)' }}>{h.date}</div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* O'ng — natija */}
        <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 12, padding: 20, minHeight: 400 }}>
          <div style={{ fontSize: 12, color: 'var(--text-muted)', letterSpacing: 1, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
            <span>🤖 GEMINI AI TAHLILI</span>
            <span style={{ padding: '2px 8px', background: '#8bc34a18', border: '1px solid #8bc34a40', borderRadius: 4, color: '#8bc34a', fontSize: 10 }}>REAL</span>
          </div>

          {!image && !loading && !result && (
            <div style={{ textAlign: 'center', paddingTop: 60 }}>
              <div style={{ fontSize: 48, marginBottom: 12 }}>🌿</div>
              <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Rasm yuklang va tahlil bosing</div>
            </div>
          )}

          {loading && (
            <div style={{ textAlign: 'center', paddingTop: 60 }}>
              <div style={{ fontSize: 36, marginBottom: 16 }}>🔬</div>
              <div style={{ color: '#8bc34a', fontFamily: 'var(--font-mono)', fontSize: 13, marginBottom: 8 }}>AI tahlil qilinmoqda...</div>
              <div style={{ color: 'var(--text-muted)', fontSize: 12 }}>Gemini Vision ishlayapti</div>
            </div>
          )}

          {result && !loading && (
            <div style={{ fontSize: 13, color: 'var(--text-primary)', lineHeight: 1.8, whiteSpace: 'pre-wrap' }}>
              {result}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
