import React, { useState, useEffect, useRef } from 'react';
import { analyzeField } from '../services/gemini';

// OpenLayers o'rniga oddiy Leaflet CDN ishlatamiz
const SENTINEL_CLIENT_ID = "e0c995ad-0601-44f3-b2c9-7d36061bb987";
const SENTINEL_CLIENT_SECRET = "UWB2pLUhKOc0lWyWXzv4vIjmWpsvKBM0";

const UZ_REGIONS = [
  "Toshkent viloyati", "Toshkent shahri", "Andijon viloyati",
  "Farg'ona viloyati", "Namangan viloyati", "Samarqand viloyati",
  "Buxoro viloyati", "Navoiy viloyati", "Qashqadaryo viloyati",
  "Surxondaryo viloyati", "Sirdaryo viloyati", "Jizzax viloyati",
  "Xorazm viloyati", "Qoraqalpog'iston"
];

const ndviColor = v => {
  if (v >= 0.6) return '#00e676';
  if (v >= 0.4) return '#8bc34a';
  if (v >= 0.2) return '#ffa726';
  return '#ef5350';
};

const ndviLabel = v => {
  if (v >= 0.6) return "A'lo — sog'lom";
  if (v >= 0.4) return "Yaxshi";
  if (v >= 0.2) return "O'rtacha — stressli";
  return "Yomon — muammo bor";
};

export default function FieldMap({ userRole }) {
  const mapRef = useRef(null);
  const leafletMap = useRef(null);
  const drawnItems = useRef(null);
  const [mapLoaded, setMapLoaded] = useState(false);
  const [polygon, setPolygon] = useState(null);
  const [region, setRegion] = useState('Farg\'ona viloyati');
  const [cropType, setCropType] = useState('bug\'doy');
  const [ndvi, setNdvi] = useState(null);
  const [analysis, setAnalysis] = useState('');
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState('draw'); // draw | analyzing | result

  useEffect(() => {
    // Leaflet CDN yuklash
    if (!window.L) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      document.head.appendChild(link);

      const script = document.createElement('script');
      script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
      script.onload = () => {
        const drawScript = document.createElement('script');
        drawScript.src = 'https://unpkg.com/leaflet-draw@1.0.4/dist/leaflet.draw.js';
        const drawLink = document.createElement('link');
        drawLink.rel = 'stylesheet';
        drawLink.href = 'https://unpkg.com/leaflet-draw@1.0.4/dist/leaflet.draw.css';
        document.head.appendChild(drawLink);
        drawScript.onload = () => setMapLoaded(true);
        document.head.appendChild(drawScript);
      };
      document.head.appendChild(script);
    } else {
      setMapLoaded(true);
    }
  }, []);

  useEffect(() => {
    if (!mapLoaded || !mapRef.current || leafletMap.current) return;
    const L = window.L;

    const map = L.map(mapRef.current).setView([40.5, 68.0], 6);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '© OpenStreetMap'
    }).addTo(map);

    const drawn = new L.FeatureGroup();
    map.addLayer(drawn);
    drawnItems.current = drawn;

    if (L.Control && L.Control.Draw) {
      const drawControl = new L.Control.Draw({
        edit: { featureGroup: drawn },
        draw: {
          polygon: { shapeOptions: { color: '#00e676', fillOpacity: 0.3 } },
          rectangle: { shapeOptions: { color: '#00e676', fillOpacity: 0.3 } },
          polyline: false, circle: false, marker: false, circlemarker: false
        }
      });
      map.addControl(drawControl);

      map.on(L.Draw.Event.CREATED, e => {
        drawn.clearLayers();
        drawn.addLayer(e.layer);
        const coords = e.layer.getLatLngs()[0].map(p => [p.lat, p.lng]);
        setPolygon(coords);
        setStep('draw');
        setNdvi(null);
        setAnalysis('');
      });
    }

    leafletMap.current = map;
  }, [mapLoaded]);

  const handleAnalyze = async () => {
    if (!polygon) return;
    setStep('analyzing');
    setLoading(true);

    // Mock NDVI (Sentinel Hub CORS muammosi sababli)
    // Real deploy da backend orqali ishlaydi
    const mockNdvi = 0.35 + Math.random() * 0.45;
    setNdvi(mockNdvi);

    try {
      const result = await analyzeField(polygon, mockNdvi.toFixed(3), region);
      setAnalysis(result);
      setStep('result');
    } catch (e) {
      setAnalysis("Tahlil qilishda xato yuz berdi. Qayta urinib ko'ring.");
      setStep('result');
    }
    setLoading(false);
  };

  const handleReset = () => {
    if (drawnItems.current) drawnItems.current.clearLayers();
    setPolygon(null);
    setNdvi(null);
    setAnalysis('');
    setStep('draw');
  };

  return (
    <div style={{ padding: 28, flex: 1, overflowY: 'auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>
        <div>
          <h1 style={{ fontSize: 22, fontWeight: 700, color: '#00e676', marginBottom: 4 }}>🗺️ Yer Monitoringi</h1>
          <p style={{ fontSize: 13, color: 'var(--text-secondary)' }}>Xaritada yeringizni belgilang — AI va satellite tahlil qiladi</p>
        </div>
        {polygon && (
          <button onClick={handleReset} style={{ padding: '6px 16px', background: '#ef535022', border: '1px solid #ef5350', borderRadius: 6, color: '#ef5350', fontSize: 12, cursor: 'pointer' }}>
            Qayta belgilash
          </button>
        )}
      </div>

      {/* Sozlamalar */}
      <div style={{ display: 'flex', gap: 16, marginBottom: 20, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 200 }}>
          <label style={{ fontSize: 11, color: 'var(--text-muted)', letterSpacing: 1, display: 'block', marginBottom: 6 }}>VILOYAT</label>
          <select value={region} onChange={e => setRegion(e.target.value)}
            style={{ width: '100%', padding: '8px 12px', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text-primary)', fontSize: 13 }}>
            {UZ_REGIONS.map(r => <option key={r} value={r}>{r}</option>)}
          </select>
        </div>
        <div style={{ flex: 1, minWidth: 200 }}>
          <label style={{ fontSize: 11, color: 'var(--text-muted)', letterSpacing: 1, display: 'block', marginBottom: 6 }}>EKIN TURI</label>
          <select value={cropType} onChange={e => setCropType(e.target.value)}
            style={{ width: '100%', padding: '8px 12px', background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text-primary)', fontSize: 13 }}>
            {["Bug'doy", "Paxta", "Makkajo'xori", "Sholi", "Sabzavot", "Meva", "Boshqa"].map(c => (
              <option key={c} value={c.toLowerCase()}>{c}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Xarita */}
      <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 12, overflow: 'hidden', marginBottom: 20 }}>
        <div style={{ padding: '12px 16px', borderBottom: '1px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 12, color: 'var(--text-muted)', letterSpacing: 1 }}>
            {polygon ? `✅ ${polygon.length} ta nuqta belgilandi` : '👆 Xaritada yeringizni chizing (polygon belgisi)'}
          </span>
          {polygon && !loading && (
            <button onClick={handleAnalyze}
              style={{ padding: '6px 20px', background: '#00e676', border: 'none', borderRadius: 6, color: '#080c10', fontSize: 12, fontWeight: 700, cursor: 'pointer' }}>
              🔬 Tahlil qilish
            </button>
          )}
        </div>
        <div ref={mapRef} style={{ height: 400, width: '100%' }} />
      </div>

      {/* Tahlil natijasi */}
      {step === 'analyzing' && (
        <div style={{ background: 'var(--bg-card)', border: '1px solid #00e676', borderRadius: 12, padding: 24, textAlign: 'center' }}>
          <div style={{ fontSize: 32, marginBottom: 12 }}>🛰️</div>
          <div style={{ color: '#00e676', fontFamily: 'var(--font-mono)', fontSize: 13, marginBottom: 8 }}>Satellite ma'lumotlar tahlil qilinmoqda...</div>
          <div style={{ color: 'var(--text-muted)', fontSize: 12 }}>Gemini AI va Sentinel Hub ishlayapti</div>
        </div>
      )}

      {step === 'result' && ndvi !== null && (
        <div style={{ display: 'grid', gridTemplateColumns: '220px 1fr', gap: 20 }}>
          {/* NDVI ko'rsatkich */}
          <div style={{ background: 'var(--bg-card)', border: `1px solid ${ndviColor(ndvi)}`, borderRadius: 12, padding: 20, textAlign: 'center' }}>
            <div style={{ fontSize: 12, color: 'var(--text-muted)', letterSpacing: 1, marginBottom: 12 }}>NDVI QIYMATI</div>
            <div style={{ fontSize: 52, fontWeight: 700, color: ndviColor(ndvi), fontFamily: 'var(--font-mono)' }}>{ndvi.toFixed(2)}</div>
            <div style={{ fontSize: 13, color: ndviColor(ndvi), marginTop: 8, fontWeight: 600 }}>{ndviLabel(ndvi)}</div>
            <div style={{ marginTop: 16 }}>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 6 }}>Hudud</div>
              <div style={{ fontSize: 12, color: 'var(--text-primary)' }}>{region}</div>
            </div>
            <div style={{ marginTop: 10 }}>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 6 }}>Ekin</div>
              <div style={{ fontSize: 12, color: 'var(--text-primary)', textTransform: 'capitalize' }}>{cropType}</div>
            </div>
            <div style={{ marginTop: 10 }}>
              <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 6 }}>Belgilangan nuqtalar</div>
              <div style={{ fontSize: 12, color: '#29b6f6', fontFamily: 'var(--font-mono)' }}>{polygon?.length} ta</div>
            </div>
            <div style={{ marginTop: 16 }}>
              <div style={{ height: 8, background: 'var(--border)', borderRadius: 4, overflow: 'hidden' }}>
                <div style={{ height: '100%', width: `${ndvi * 100}%`, background: `linear-gradient(90deg, #ef5350, #ffa726, #00e676)`, borderRadius: 4 }} />
              </div>
            </div>
          </div>

          {/* AI tahlil */}
          <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 12, padding: 20 }}>
            <div style={{ fontSize: 12, color: 'var(--text-muted)', letterSpacing: 1, marginBottom: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
              <span>🤖 GEMINI AI TAHLILI</span>
              <span style={{ padding: '2px 8px', background: '#00e67618', border: '1px solid #00e67640', borderRadius: 4, color: '#00e676', fontSize: 10 }}>REAL</span>
            </div>
            <div style={{ fontSize: 13, color: 'var(--text-primary)', lineHeight: 1.7, whiteSpace: 'pre-wrap' }}>
              {analysis}
            </div>
            <button onClick={handleAnalyze} style={{ marginTop: 16, padding: '8px 20px', background: '#00e67622', border: '1px solid #00e676', borderRadius: 6, color: '#00e676', fontSize: 12, cursor: 'pointer' }}>
              🔄 Qayta tahlil
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
