import React, { useState, useEffect } from 'react';
import './index.css';
import { AuthProvider, useAuth, ROLE_CONFIG } from './auth/AuthContext';
import LoginPage from './pages/LoginPage';
import Sidebar from './components/Sidebar';
import ErrorBoundary from './components/ErrorBoundary';
import AgroMonitor from './modules/AgroMonitor';
import KadastrMonitor from './modules/KadastrMonitor';
import HeatMap from './modules/HeatMap';
import WasteDetector from './modules/WasteDetector';
import SeismicMonitor from './modules/SeismicMonitor';
import FieldMap from './modules/FieldMap';
import DiseaseDetector from './modules/DiseaseDetector';

const modules = {
  agro: AgroMonitor,
  field: FieldMap,
  disease: DiseaseDetector,
  kadastr: KadastrMonitor,
  heat: HeatMap,
  waste: WasteDetector,
  seismic: SeismicMonitor,
};

const moduleColors = {
  agro: '#00e676', field: '#29b6f6', disease: '#8bc34a',
  kadastr: '#ffa726', heat: '#ff7043', waste: '#ab47bc', seismic: '#ef5350',
};

function Dashboard() {
  const { user, logout } = useAuth();
  const [active, setActive] = useState('agro');
  const [time, setTime] = useState(new Date());
  const [alerts] = useState([
    { msg: 'M4.2 zilzila — Surxondaryo', color: '#ef5350' },
    { msg: "680 ga noqonuniy yer — Qoraqalpog'iston", color: '#ffa726' },
    { msg: 'Kimyoviy chiqindi aniqlandi — Samarqand', color: '#ab47bc' },
    { msg: 'Farg\'ona — NDVI past (0.28) aniqlandi', color: '#8bc34a' },
  ]);
  const [alertIdx, setAlertIdx] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    const t = setInterval(() => setAlertIdx(i => (i + 1) % alerts.length), 4000);
    return () => clearInterval(t);
  }, [alerts.length]);

  const ActiveModule = modules[active];
  const roleInfo = ROLE_CONFIG[user?.role] || {};

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}>
      <header style={{
        height: 48, background: 'var(--bg-card)', borderBottom: '1px solid var(--border)',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 24px', flexShrink: 0, zIndex: 100,
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1 }}>
          <span style={{ fontSize: 10, color: 'var(--text-muted)', letterSpacing: 1, flexShrink: 0 }}>LIVE ALERT</span>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 6, height: 6, borderRadius: '50%', background: alerts[alertIdx].color, boxShadow: `0 0 6px ${alerts[alertIdx].color}`, flexShrink: 0 }} />
            <span style={{ fontSize: 12, color: alerts[alertIdx].color, fontFamily: 'var(--font-mono)', whiteSpace: 'nowrap' }}>
              {alerts[alertIdx].msg}
            </span>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <div style={{ fontSize: 10, color: 'var(--text-muted)', fontFamily: 'var(--font-mono)', letterSpacing: 1 }}>
            {time.toUTCString().slice(17, 25)} UTC
          </div>
          <div style={{ display: 'flex', gap: 6 }}>
            {['S2A', 'S2B', 'MOD', 'AI'].map(sat => (
              <span key={sat} style={{ fontSize: 9, padding: '2px 7px', borderRadius: 4, background: '#00e67618', border: '1px solid #00e67640', color: '#00e676', fontFamily: 'var(--font-mono)', letterSpacing: 1 }}>{sat}</span>
            ))}
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, justifyContent: 'flex-end' }}>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: 11, color: 'var(--text-primary)', fontWeight: 600 }}>
              {roleInfo.icon} {user?.name}
            </div>
            <div style={{ fontSize: 10, color: 'var(--text-muted)', fontFamily: 'var(--font-mono)' }}>
              {roleInfo.label}
            </div>
          </div>
          <button onClick={logout} style={{ padding: '4px 12px', background: '#ef535018', border: '1px solid #ef535040', borderRadius: 6, color: '#ef5350', fontSize: 11, cursor: 'pointer' }}>
            Chiqish
          </button>
        </div>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        <Sidebar active={active} onSelect={setActive} userRole={user?.role} />
        <main style={{ flex: 1, overflowY: 'auto', borderLeft: `2px solid ${moduleColors[active]}`, transition: 'border-color 0.3s' }}>
          <ErrorBoundary key={active}>
            <ActiveModule userRole={user?.role} />
          </ErrorBoundary>
        </main>
      </div>
    </div>
  );
}

function AppContent() {
  const { user, loading } = useAuth();
  if (loading) return (
    <div style={{ minHeight: '100vh', background: '#080c10', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ color: '#00e676', fontFamily: 'monospace', fontSize: 14 }}>🛰️ Yuklanmoqda...</div>
    </div>
  );
  return user ? <Dashboard /> : <LoginPage />;
}

export default function App() {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}
